window.SAOMD_STORIES[410401101]={"id":410401101,"branches":[],"frames":[{"id":1,"order":1,"actions":[{"uid":"410401101:1:1","speaker":"Alice","text":"I'm...confused.","pose":10540108,"background":"bg_event_christmas_town","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我……很困惑。"},{"uid":"410401101:1:2","speaker":"Eugeo","text":"","pose":10530208,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":2,"order":2,"actions":[{"uid":"410401101:2:1","speaker":"Eugeo","text":"Wow, the town's so...festive!\nWhat are all these decorations?","pose":10530204,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"哇，小镇好…喜庆啊！这些装饰是什么？"}]},{"id":3,"order":3,"actions":[{"uid":"410401101:3:1","speaker":"Kirito","text":"Ha ha, welcome to Christmas\nseason, guys. All of this is part\nof a winter festival.","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"哈哈，欢迎来到圣诞节，伙计们。所有这一切都是冬季节日的一部分。"},{"uid":"410401101:3:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":4,"order":4,"actions":[{"uid":"410401101:4:1","speaker":"Asuna","text":"Remember how we had Halloween\na couple of months back? This is\nlike that, but more jolly.","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"还记得几个月前我们是怎么过万圣节的吗？就是这样，但更快乐。"}]},{"id":5,"order":5,"actions":[{"uid":"410401101:5:1","speaker":"Alice","text":"I see. I'm noticing a lot of\nglitter and blinking lights. Are\nthey powered by Elements...?","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"原来如此。我注意到有很多闪光和闪烁的灯光。它们是由元素驱动的吗……？"},{"uid":"410401101:5:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":6,"order":6,"actions":[{"uid":"410401101:6:1","speaker":"Eugeo","text":"Hmm, there are a lot of flashing\nthings, huh? And look! All the\nfairies seem to be in a good mood!","pose":10530204,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"嗯，闪烁的东西很多吧？看！看来小仙女们心情都很好啊！"}]},{"id":7,"order":7,"actions":[{"uid":"410401101:7:1","speaker":"Kirito","text":"Yup! Despite the cold and the\nsnow, everyone's having a grand\nold time.","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"是啊！尽管寒冷和大雪，每个人都度过了一段美好的时光。"},{"uid":"410401101:7:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":8,"order":8,"actions":[{"uid":"410401101:8:1","speaker":"Asuna","text":"Hehe, that's because it's\nChristmas! How can you\nnot have fun!","pose":10020904,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"呵呵，因为是圣诞节啊！怎能不玩得尽兴！"}]},{"id":9,"order":9,"actions":[{"uid":"410401101:9:1","speaker":"Kirito","text":"Pretty much everyone in the world\nloves Christmas. Especially kids.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"世界上几乎每个人都喜欢圣诞节。尤其是孩子们。"}]},{"id":10,"order":10,"actions":[{"uid":"410401101:10:1","speaker":"Alice","text":"I...don't understand.\nIt's noisy and busy...","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我……听不懂。这里又吵又忙……"},{"uid":"410401101:10:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":11,"order":11,"actions":[{"uid":"410401101:11:1","speaker":"Alice","text":"And all these blinking lights\nbother my eyes.","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"所有这些闪烁的灯光都让我眼睛不舒服。"}]},{"id":12,"order":12,"actions":[{"uid":"410401101:12:1","speaker":"Kirito","text":"I guess maybe Christmas isn't for\nyou, Alice?","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我想也许圣诞节不适合你吧，爱丽丝？"},{"uid":"410401101:12:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":13,"order":13,"actions":[{"uid":"410401101:13:1","speaker":"Alice","text":"...","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"..."},{"uid":"410401101:13:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":14,"order":14,"actions":[{"uid":"410401101:14:1","speaker":"???","text":"La la la!","pose":2,"background":"","item":"","illustration":"","speaker_zh":"？？？","text_zh":"啦啦啦！"}]},{"id":15,"order":15,"actions":[{"uid":"410401101:15:1","speaker":"Alice","text":"I hear...singing?","pose":10540103,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我听到……唱歌？"}]},{"id":16,"order":16,"actions":[{"uid":"410401101:16:1","speaker":"Eugeo","text":"I think it's coming from that\nbuilding.","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"我想是从那栋楼传来的。"}]},{"id":17,"order":17,"actions":[{"uid":"410401101:17:1","speaker":"Asuna","text":"That's a church, which means that\nsong's probably a Christmas carol.","pose":10020903,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"那是一座教堂，这意味着这首歌可能是圣诞颂歌。"},{"uid":"410401101:17:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":18,"order":18,"actions":[{"uid":"410401101:18:1","speaker":"Alice","text":"A church, you say?","pose":10540103,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"你说教堂？"},{"uid":"410401101:18:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":19,"order":19,"actions":[{"uid":"410401101:19:1","speaker":"Eugeo","text":"A carol, you say?","pose":10530203,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"你说颂歌？"}]},{"id":20,"order":20,"actions":[{"uid":"410401101:20:1","speaker":"Asuna","text":"Where to start... People sing\nspecial songs called carols during\nthe Christmas season.","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"从哪里开始...人们在圣诞节期间唱特殊的歌曲，称为颂歌。"},{"uid":"410401101:20:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":21,"order":21,"actions":[{"uid":"410401101:21:1","speaker":"Asuna","text":"You see, Christmas was originally\na religious holiday, though just\nabout everyone celebrates it now.","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"你看，圣诞节原本是一个宗教节日，但现在几乎每个人都庆祝它。"}]},{"id":22,"order":22,"actions":[{"uid":"410401101:22:1","speaker":"Asuna","text":"So a lot of carols--also called\n\"noels\"--were composed as\nkinda holy hymns for Christmas.","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"所以很多颂歌——也叫“诺埃尔”——被创作成了圣诞圣歌。"}]},{"id":23,"order":23,"actions":[{"uid":"410401101:23:1","speaker":"Eugeo","text":"Holy hymns... I guess that's why\nthese songs seem so...gentle\nyet dignified.","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"神圣的赞美诗……我想这就是为什么这些歌曲看起来如此……温柔而庄严。"},{"uid":"410401101:23:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":24,"order":24,"actions":[{"uid":"410401101:24:1","speaker":"Alice","text":"These gaudy decorations bother\nme, but these songs are worth\nlistening to.","pose":10540104,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"这些花哨的装饰让我很烦恼，但是这些歌值得一听。"}]},{"id":25,"order":25,"actions":[{"uid":"410401101:25:1","speaker":"Alice","text":"They...fill my heart with a\nsolemn joy.","pose":10540104,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"他们……让我的心里充满了庄严的喜悦。"}]},{"id":26,"order":26,"actions":[{"uid":"410401101:26:1","speaker":"Kirito","text":"Ha ha, I guess Christmas isn't\nyour thing, but Christmas carols\nare!","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"哈哈，我猜圣诞节不是你的菜，但圣诞颂歌是你的菜！"},{"uid":"410401101:26:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":27,"order":27,"actions":[{"uid":"410401101:27:1","speaker":"Kirito","text":"In that case, why don't we go in?\nThey might let us listen up close.","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"既然如此，我们为什么不进去呢？他们可能会让我们近距离聆听。"}]},{"id":28,"order":28,"actions":[{"uid":"410401101:28:1","speaker":"Alice","text":"No, that's all right...\nI wouldn't want to impose.","pose":105401082,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"不，没关系……我不想强加。"},{"uid":"410401101:28:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":29,"order":29,"actions":[{"uid":"410401101:29:1","speaker":"Kirito","text":"Nah, it's fine. Now, we're going,\nand you're coming with us!","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"嗯，没关系。现在，我们走了，你也跟我们一起走吧！"},{"uid":"410401101:29:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":30,"order":30,"actions":[{"uid":"410401101:30:1","speaker":"Asuna","text":"Hehe, sounds like fun!","pose":10020904,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"呵呵，听起来很好玩！"}]},{"id":31,"order":31,"actions":[{"uid":"410401101:31:1","speaker":"Eugeo","text":"Come on, Alice! Please? I want\nto hear them up close too!","pose":10530204,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"加油，爱丽丝！请？我也想近距离听听他们的声音！"},{"uid":"410401101:31:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":32,"order":32,"actions":[{"uid":"410401101:32:1","speaker":"Alice","text":"V-Very well... Besides, I'm\ninterested in seeing this\nchurch of yours...","pose":10540103,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"好、好……另外，我也有兴趣看看你们的这座教堂……"}]},{"id":33,"order":33,"actions":[{"uid":"410401101:33:1","speaker":"Carolers","text":"Siiiiiilent Niiiiight...","pose":3,"background":"bg_12_church_room","item":"","illustration":"","speaker_zh":"颂歌歌手们","text_zh":"平——安——夜——……"},{"uid":"410401101:33:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410401101:33:3","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":34,"order":34,"actions":[{"uid":"410401101:34:1","speaker":"Kirito","text":"Whoa... These carolers are really\ngood...","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"哇哦……这些颂歌真的很好听……"}]},{"id":35,"order":35,"actions":[{"uid":"410401101:35:1","speaker":"Asuna","text":"Yeah, and they've got both kids\nand adults singing. It's such a\nclear, beautiful sound...","pose":10020904,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"是的，而且他们有小孩和大人在唱歌。这是多么清晰、美妙的声音……"}]},{"id":36,"order":36,"actions":[{"uid":"410401101:36:1","speaker":"Alice","text":"Fairies they may be, but they have\nthe voices of angels. Do they have\nsome special Calling?","pose":10540103,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"她们虽然是仙女，却有着天使般的声音。他们有什么特殊的召唤吗？"},{"uid":"410401101:36:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":37,"order":37,"actions":[{"uid":"410401101:37:1","speaker":"Asuna","text":"Hehe! No, silly! They've all just\npracticed really hard.","pose":10020904,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"呵呵！不，傻瓜！他们都非常努力地练习过。"},{"uid":"410401101:37:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":38,"order":38,"actions":[{"uid":"410401101:38:1","speaker":"Asuna","text":"I assume, anyway.","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"我想，无论如何。"}]},{"id":39,"order":39,"actions":[{"uid":"410401101:39:1","speaker":"Alice","text":"It's...incredible. To think that\ntraining could produce a sound\nso sublime...","pose":10540104,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"这……太不可思议了。没想到训练可以发出如此美妙的声音......"},{"uid":"410401101:39:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":40,"order":40,"actions":[{"uid":"410401101:40:1","speaker":"Eugeo","text":"It's moved me too, Alice.\nI'm glad we came.","pose":10530204,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"我也很感动，爱丽丝。我很高兴我们来了。"}]},{"id":41,"order":41,"actions":[{"uid":"410401101:41:1","speaker":"Alice","text":"...","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"..."}]},{"id":42,"order":42,"actions":[{"uid":"410401101:42:1","speaker":"???","text":"Hmm? What are you guys doing here?","pose":2,"background":"","item":"","illustration":"","speaker_zh":"？？？","text_zh":"嗯？你们在这儿做什么？"},{"uid":"410401101:42:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""},{"uid":"410401101:42:3","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":43,"order":43,"actions":[{"uid":"410401101:43:1","speaker":"Kirito","text":"Well, if it isn't Seven!","pose":10011503,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"好吧，如果不是赛玟的话！"},{"uid":"410401101:43:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":44,"order":44,"actions":[{"uid":"410401101:44:1","speaker":"Seven","text":"Heh, don't tell me the dulcet\ntones of my carolers beckoned\nyou hither?","pose":10130104,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"呵呵，难道是我优美的颂歌在召唤你来这里吗？"}]},{"id":45,"order":45,"actions":[{"uid":"410401101:45:1","speaker":"Asuna","text":"My carolers?","pose":10020903,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"我的颂歌？"}]},{"id":46,"order":46,"actions":[{"uid":"410401101:46:1","speaker":"Seven","text":"You bet they're mine! I'm the\nleader of this little troupe!","pose":10130105,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"你敢打赌，它们是我的！我是这个小剧团的队长！"}]},{"id":47,"order":47,"actions":[{"uid":"410401101:47:1","speaker":"Seven","text":"The player who came up with the\nidea practically begged me to whip\nthese guys into singing shape.","pose":10130105,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"提出这个主意的玩家几乎是求我把这些家伙鞭打成唱歌的样子。"}]},{"id":48,"order":48,"actions":[{"uid":"410401101:48:1","speaker":"Seven","text":"Besides, everyone who joined up\nis a Pooka or just likes singing,\nso it's an easy gig.","pose":10130105,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"而且参加的都是音乐精灵或者只是喜欢唱歌，所以演出很轻松。"}]},{"id":49,"order":49,"actions":[{"uid":"410401101:49:1","speaker":"Kirito","text":"Cool. Come to think of it, a lot\nof your songs are surprisingly\nmelodic too.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"酷。想想看，你的很多歌曲的旋律也令人惊讶。"}]},{"id":50,"order":50,"actions":[{"uid":"410401101:50:1","speaker":"Seven","text":"What do you mean, \"surprisingly\"?!","pose":10130101,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"“令人惊讶”是什么意思？！"}]},{"id":51,"order":51,"actions":[{"uid":"410401101:51:1","speaker":"Kirito","text":"Er, I just meant that you're an\nidol, right? I thought your songs\nwould be more...peppy?","pose":100115032,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"呃，我只是想说你是偶像吧？我以为你的歌会更...活泼？"}]},{"id":52,"order":52,"actions":[{"uid":"410401101:52:1","speaker":"Asuna","text":"You're digging that hole deeper,\nKirito. Anyway, with you at their\nhead, no wonder they're so good.","pose":10020904,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"你把坑挖得更深了，桐人。无论如何，有你在他们的带领下，难怪他们这么优秀。"}]},{"id":53,"order":53,"actions":[{"uid":"410401101:53:1","speaker":"Seven","text":"Right?!","pose":10130104,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"对吧？！"},{"uid":"410401101:53:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":54,"order":54,"actions":[{"uid":"410401101:54:1","speaker":"Eugeo","text":"So you're friends with this girl?\nIn that case, hi there! My name's\nEugeo. Nice to meet you!","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"所以你和这个女孩是朋友？在这种情况下，你好！我的名字是尤吉欧。很高兴见到你！"},{"uid":"410401101:54:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":55,"order":55,"actions":[{"uid":"410401101:55:1","speaker":"Alice","text":"You may call me Alice Synthesis\nThirty.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"你可以叫我爱丽丝综合三十。"}]},{"id":56,"order":56,"actions":[{"uid":"410401101:56:1","speaker":"Seven","text":"Ahh, so you're these two warriors\nfrom another dimension I've heard\nso much about. Cool.","pose":10130108,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"啊啊，你们就是我听过很多次的来自异次元的战士了。凉爽的。"},{"uid":"410401101:56:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410401101:56:3","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":57,"order":57,"actions":[{"uid":"410401101:57:1","speaker":"Seven","text":"I'm told you two are ridiculously\ngood at fighting.","pose":10130105,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"听说你们两个打斗能力高得离谱。"}]},{"id":58,"order":58,"actions":[{"uid":"410401101:58:1","speaker":"Kirito","text":"It's literally insane how good\nthey are.","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"他们真的太棒了。"}]},{"id":59,"order":59,"actions":[{"uid":"410401101:59:1","speaker":"Seven","text":"Hmm... Convenient! I think I have\na job for two ultimate warriors\nlike yourselves...","pose":10130108,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"嗯……方便！我想我有一份工作适合像你们这样的两个终极战士......"}]},{"id":60,"order":60,"actions":[{"uid":"410401101:60:1","speaker":"Seven","text":"You two can help too. So, Kirito,\nAsuna... Want to go on a little\nquest for me?","pose":10130104,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"你们两个也可以帮忙。那么，桐人、亚丝娜...想帮我做点小任务吗？"}]},{"id":61,"order":61,"actions":[{"uid":"410401101:61:1","speaker":"Kirito","text":"Maybe? I need more info.","pose":10011503,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"也许吧？我需要更多信息。"}]},{"id":62,"order":62,"actions":[{"uid":"410401101:62:1","speaker":"Seven","text":"My carolers need some bodyguards,\nand I want you for the job.","pose":10130105,"background":"bg_12_church_room","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"我的颂歌需要一些保镖，我需要你来做这份工作。"},{"uid":"410401101:62:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410401101:62:3","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":63,"order":63,"actions":[{"uid":"410401101:63:1","speaker":"Kirito","text":"Bodyguards? For carolers?\nJust what are we supposed to\nprotect you from, music critics?","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"保镖？为颂歌者？音乐评论家，我们应该保护你们免受什么伤害？"}]},{"id":64,"order":64,"actions":[{"uid":"410401101:64:1","speaker":"Seven","text":"Ha ha, very funny. No, we've got\nsome slippery monsters after our\ncaroling hides.","pose":10130102,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"哈哈，很好笑。不，在我们的颂歌隐藏之后，我们遇到了一些狡猾的怪物。"}]},{"id":65,"order":65,"actions":[{"uid":"410401101:65:1","speaker":"Asuna","text":"Uhh...what? How does that even\nmake sense? You carolers are\na player-ru--","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"呃……什么？这有什么意义呢？你们颂歌者是玩家-ru--"}]},{"id":66,"order":66,"actions":[{"uid":"410401101:66:1","speaker":"Asuna","text":"Er, I mean fairy-led volunteer\neffort, right? Why would monsters\ntarget you?","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"呃，我是说仙女主导的志愿者活动，对吗？为什么怪物会瞄准你？"}]},{"id":67,"order":67,"actions":[{"uid":"410401101:67:1","speaker":"Seven","text":"Zero idea. We thought it was\njust random bad luck at first,\nbut they're definitely after us.","pose":10130106,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"零想法。起初我们以为这只是随机的坏运气，但他们肯定是在追我们。"}]},{"id":68,"order":68,"actions":[{"uid":"410401101:68:1","speaker":"Seven","text":"And ugh! It's always weird and\nstrong monsters, and they spawn\nright next of us!","pose":10130106,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"呃！怪物总是怪异而强大，而且它们就在我们旁边生成！"},{"uid":"410401101:68:2","speaker":"Asuna","text":"","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":69,"order":69,"actions":[{"uid":"410401101:69:1","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""},{"uid":"410401101:69:2","speaker":"Eugeo","text":"You said your group's mostly\nPooka, right? Pooka are relatively\nweak for fairies, correct?","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"你说你们组大部分是音乐精灵，对吧？ 音乐精灵对于仙女来说是比较弱的吧？"}]},{"id":70,"order":70,"actions":[{"uid":"410401101:70:1","speaker":"Kirito","text":"Yeah, wow. I'm surprised you\nremembered that! You're really\nlearning a lot about us, Eugeo.","pose":10011503,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"是啊，哇。我很惊讶你还记得这一点！你真的对我们有了很多了解，尤吉欧。"},{"uid":"410401101:70:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410401101:70:3","speaker":"Seven","text":"","pose":10130105,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":""}]},{"id":71,"order":71,"actions":[{"uid":"410401101:71:1","speaker":"Alice","text":"Monsters usually attack at random,\nso you think something is behind\nthis unusual behavior?","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"怪物通常会随机攻击，所以你认为这种异常行为背后有什么原因吗？"},{"uid":"410401101:71:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":72,"order":72,"actions":[{"uid":"410401101:72:1","speaker":"Asuna","text":"Double wow. Alice, you've got\ngreat insight.","pose":10020903,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"双重哇。 爱丽丝，你的洞察力很强。"},{"uid":"410401101:72:2","speaker":"Seven","text":"","pose":10130105,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":""},{"uid":"410401101:72:3","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":73,"order":73,"actions":[{"uid":"410401101:73:1","speaker":"Alice","text":"We've been in this world for some\ntime now. It's only natural that\nwe'd pick up on your world's rules.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我们来到这个世界已经有一段时间了。我们自然会接受你们世界的规则。"},{"uid":"410401101:73:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":74,"order":74,"actions":[{"uid":"410401101:74:1","speaker":"Eugeo","text":"Hmm... If a fairy is behind this,\nit would have to be a Cait Sith.","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"嗯……如果是仙女的话，那一定是猫妖了。"}]},{"id":75,"order":75,"actions":[{"uid":"410401101:75:1","speaker":"Alice","text":"They are the only fairies\ncapable of temporarily\ncontrolling monsters...","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"她们是唯一能够暂时控制怪物的精灵……"}]},{"id":76,"order":76,"actions":[{"uid":"410401101:76:1","speaker":"Alice","text":"Which means we may find a Cait\nSith lurking in the shadows nearby\nwhen the monsters attack.","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"这意味着当怪物攻击时我们可能会发现潜伏在附近阴影中的凯特西斯。"}]},{"id":77,"order":77,"actions":[{"uid":"410401101:77:1","speaker":"Kirito","text":"Ha ha, wow! That's exactly what\nI was thinking.","pose":100115042,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"哈哈，哇！这正是我的想法。"},{"uid":"410401101:77:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410401101:77:3","speaker":"Seven","text":"","pose":10130105,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":""}]},{"id":78,"order":78,"actions":[{"uid":"410401101:78:1","speaker":"Asuna","text":"I'm...kinda shocked. Kirito,\nthey totally stole your thunder!","pose":100209042,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"我……有点震惊。 桐人，他们完全抢了你的风头！"}]},{"id":79,"order":79,"actions":[{"uid":"410401101:79:1","speaker":"Seven","text":"Wow, okay! You two have officially\nimpressed me! Now come on, let's\ngo! The pay's great, promise!","pose":10130104,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"哇，好吧！你们两个给我留下了深刻的印象！现在来吧，我们走吧！薪水很高，保证！"}]},{"id":80,"order":80,"actions":[{"uid":"410401101:80:1","speaker":"Kirito","text":"I think Asuna and I are down.\nWhat about you guys?","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我觉得我和亚丝娜都很沮丧。你们呢？"},{"uid":"410401101:80:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":81,"order":81,"actions":[{"uid":"410401101:81:1","speaker":"Alice","text":"Normally I'd prioritize our search\nfor the Divine Objects, but I\ncan't ignore your friend's plight.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"一般情况下我都会优先寻找神器，但我不能忽视你朋友的困境。"},{"uid":"410401101:81:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":82,"order":82,"actions":[{"uid":"410401101:82:1","speaker":"Eugeo","text":"Yeah, and I want to pay you guys\nback for letting me listen to your\nwonderful song!","pose":10530204,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"是的，我想回报你们让我听到你们美妙的歌曲！"}]},{"id":83,"order":83,"actions":[{"uid":"410401101:83:1","speaker":"Kirito","text":"Then it's settled!\nSeven...quest accepted!","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"那就这么定了！ 赛玟...任务已接受！"},{"uid":"410401101:83:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410401101:83:3","speaker":"Seven","text":"","pose":10130105,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":""}]},{"id":84,"order":84,"actions":[{"uid":"410401101:84:1","speaker":"Seven","text":"Spasiba!\nYou're the best!","pose":10130104,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"斯帕西巴！你是最棒的！"}]},{"id":85,"order":85,"actions":[{"uid":"410401101:85:1","speaker":"Seven","text":"You guys ready to escort us today?","pose":10130105,"background":"bg_event_alne_field_christmas","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"今天你们准备好护送我们了吗？"},{"uid":"410401101:85:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410401101:85:3","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":86,"order":86,"actions":[{"uid":"410401101:86:1","speaker":"Kirito","text":"Totally. I'm impressed that you're\ncaroling around in so many\ndifferent places, though.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"完全可以。不过，你在这么多不同的地方唱颂歌，给我留下了深刻的印象。"}]},{"id":87,"order":87,"actions":[{"uid":"410401101:87:1","speaker":"Seven","text":"Well, compared to all the effort\nwe spent practicing, this is easy.\nBesides, we want to carol.","pose":10130105,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"嗯，相对于我们付出的努力练习来说，这很容易。此外，我们还想唱颂歌。"}]},{"id":88,"order":88,"actions":[{"uid":"410401101:88:1","speaker":"Seven","text":"It just sucks that we're getting\nattacked for doing it...","pose":101301032,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"我们因为这么做而受到攻击真是太糟糕了……"}]},{"id":89,"order":89,"actions":[{"uid":"410401101:89:1","speaker":"Asuna","text":"But it's not like this is the only\nthing you guys have on your\nplates...","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"不过你们的盘子里又不是只有这个……"}]},{"id":90,"order":90,"actions":[{"uid":"410401101:90:1","speaker":"Asuna","text":"There's questing to be done,\nand seasonal events, and guild\nactivities...","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"有任务要做，还有季节活动，还有公会活动……"}]},{"id":91,"order":91,"actions":[{"uid":"410401101:91:1","speaker":"Alice","text":"From what I've learned, this is\nthe only time of the year you\ncan carol.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"据我所知，这是一年中唯一可以唱颂歌的时候。"},{"uid":"410401101:91:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":92,"order":92,"actions":[{"uid":"410401101:92:1","speaker":"Alice","text":"As such, it would be a shame to\nhide in town. You want to share\nyour songs with the world, right?","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"这样的话，躲在城里就太可惜了。您想与世界分享您的歌曲，对吗？"}]},{"id":93,"order":93,"actions":[{"uid":"410401101:93:1","speaker":"Seven","text":"Exactly! And that's why Seven's\nCarolers are going on tour!","pose":10130104,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"没错！这就是赛玟的 Carolers 进行巡演的原因！"},{"uid":"410401101:93:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410401101:93:3","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":94,"order":94,"actions":[{"uid":"410401101:94:1","speaker":"Asuna","text":"Hehe... If you want to phrase that\nfor this world, you've become\ntraveling minstrels.","pose":10020904,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"呵呵……如果你要为这个世界表达这句话，你就成了旅行吟游诗人了。"}]},{"id":95,"order":95,"actions":[{"uid":"410401101:95:1","speaker":"Kirito","text":"Which makes me wonder even more...\nWho's attacking you, and why?","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"这让我更加好奇……是谁在攻击你，为什么？"}]},{"id":96,"order":96,"actions":[{"uid":"410401101:96:1","speaker":"Asuna","text":"Yeah, seriously... Our suspect is\na Cait Sith, but I can't fathom\ntheir motives...","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"是的，说实话……我们的嫌疑人是猫妖，但我无法理解他们的动机……"}]},{"id":97,"order":97,"actions":[{"uid":"410401101:97:1","speaker":"Monster","text":"Grawwwrgh!!","pose":1,"background":"","item":"","illustration":"","speaker_zh":"怪物","text_zh":"吼啊啊！"}]},{"id":98,"order":98,"actions":[{"uid":"410401101:98:1","speaker":"Seven","text":"Wah! And right on cue...\nWe've got company, guys!","pose":101301082,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"哇！就在这时……我们有同伴了，伙计们！"}]},{"id":99,"order":99,"actions":[{"uid":"410401101:99:1","speaker":"Kirito","text":"The second we left the safe zone,\ntoo! Alright, people, defend the\ncarolers!","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我们也是第二次离开安全区了！好吧，人们，保卫颂歌！"},{"uid":"410401101:99:2","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":100,"order":100,"actions":[{"uid":"410401101:100:1","speaker":"Eugeo","text":"You got it!","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"你懂了！"},{"uid":"410401101:100:2","speaker":"Alice","text":"","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":101,"order":101,"actions":[{"uid":"410401101:101:1","speaker":"Asuna","text":"Yeah!","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"嗯！"},{"uid":"410401101:101:2","speaker":"Seven","text":"","pose":10130107,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":""},{"uid":"410401101:101:3","speaker":"Kirito","text":"","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":102,"order":102,"actions":[{"uid":"410401101:102:1","speaker":"Alice","text":"...","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"..."},{"uid":"410401101:102:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":103,"order":103,"actions":[{"uid":"410401101:103:1","speaker":"Kirito","text":"What is it, Alice?","pose":10011503,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"什么啊，爱丽丝？"},{"uid":"410401101:103:2","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410401101:103:3","speaker":"Seven","text":"","pose":10130107,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":""}]},{"id":104,"order":104,"actions":[{"uid":"410401101:104:1","speaker":"Alice","text":"I sense a dark presence...\nI've never felt this particular\nevil before, but I can tell...","pose":105401072,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我感觉到一股黑暗的存在……我以前从未感受过这种特殊的邪恶，但我能感觉到……"},{"uid":"410401101:104:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":105,"order":105,"actions":[{"uid":"410401101:105:1","speaker":"Alice","text":"These were once sealed demons,\nand they're after the Divine\nObjects!","pose":105401072,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"这些曾经是被封印的恶魔，他们的目标是神物！"}]},{"id":106,"order":106,"actions":[{"uid":"410401101:106:1","speaker":"Kirito","text":"They're what?!","pose":100115082,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"它们是什么？！"},{"uid":"410401101:106:2","speaker":"Asuna","text":"","pose":10020908,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410401101:106:3","speaker":"Seven","text":"","pose":10130108,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":""}]},{"id":107,"order":107,"actions":[{"uid":"410401101:107:1","speaker":"Eugeo","text":"She's right... They definitely\nare far more fearsome than\nthe average monster...","pose":105302072,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"是的……它们确实比一般的怪物可怕得多……"},{"uid":"410401101:107:2","speaker":"Alice","text":"","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":108,"order":108,"actions":[{"uid":"410401101:108:1","speaker":"Asuna","text":"Now that you mention it, I think\nI get the same vibe...","pose":100209032,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"听你这么一说，我觉得我也有同样的感觉……"},{"uid":"410401101:108:2","speaker":"Seven","text":"","pose":10130107,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":""},{"uid":"410401101:108:3","speaker":"Kirito","text":"","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":109,"order":109,"actions":[{"uid":"410401101:109:1","speaker":"Monster","text":"Grawwwwrgh!","pose":1,"background":"","item":"","illustration":"","speaker_zh":"怪物","text_zh":"吼啊啊！"}]},{"id":110,"order":110,"actions":[{"uid":"410401101:110:1","speaker":"Kirito","text":"Thinking later, stabbing now!","pose":100115012,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"回头想想，现在就刺！"},{"uid":"410401101:110:2","speaker":"Asuna","text":"","pose":100209072,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":111,"order":111,"actions":[{"uid":"410401101:111:1","speaker":"Alice","text":"Of course!","pose":105401072,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"当然！"},{"uid":"410401101:111:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":112,"order":112,"actions":[{"uid":"410401101:112:1","speaker":"Asuna","text":"I'm done over here!","pose":10020905,"background":"bg_event_alne_field_christmas","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"我完了！"},{"uid":"410401101:112:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410401101:112:3","speaker":"Seven","text":"","pose":10130105,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":""}]},{"id":113,"order":113,"actions":[{"uid":"410401101:113:1","speaker":"Eugeo","text":"I've finished my opponents\nas well.","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"我也干掉了对手。"},{"uid":"410401101:113:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":114,"order":114,"actions":[{"uid":"410401101:114:1","speaker":"Kirito","text":"Great, everyone's okay.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"太好了，大家都没事。"},{"uid":"410401101:114:2","speaker":"Seven","text":"","pose":10130105,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":""},{"uid":"410401101:114:3","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":115,"order":115,"actions":[{"uid":"410401101:115:1","speaker":"Seven","text":"*sigh*... Every. Single. Time!!\nThese things really push my\nbuttons!","pose":10130106,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"*叹息*...每一个。单身的。时间！！这些事情真的让我很恼火！"},{"uid":"410401101:115:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":116,"order":116,"actions":[{"uid":"410401101:116:1","speaker":"Alice","text":"You understand now that you've\nfought them too, right?","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"你现在明白你也和他们战斗过了吧？"},{"uid":"410401101:116:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":117,"order":117,"actions":[{"uid":"410401101:117:1","speaker":"Alice","text":"You know what sort of beast it is\nwe face.","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"你知道我们面对的是什么样的野兽。"}]},{"id":118,"order":118,"actions":[{"uid":"410401101:118:1","speaker":"Kirito","text":"Yeah, for sure. And they're crazy\nstrong, too. There's no doubt\nthey're Divine Object monsters.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"是的，当然。而且他们也非常强大。毫无疑问他们是神器怪物。"},{"uid":"410401101:118:2","speaker":"Seven","text":"","pose":10130107,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":""},{"uid":"410401101:118:3","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":119,"order":119,"actions":[{"uid":"410401101:119:1","speaker":"Asuna","text":"Yeah... There's no denying that...","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"是啊……无可否认……"}]},{"id":120,"order":120,"actions":[{"uid":"410401101:120:1","speaker":"Eugeo","text":"But then all this makes even less\nsense! Why are they attacking\nthese carolers?","pose":10530202,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"但是这一切就更没有意义了！他们为什么攻击这些颂歌者？"},{"uid":"410401101:120:2","speaker":"Alice","text":"","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":121,"order":121,"actions":[{"uid":"410401101:121:1","speaker":"Caroler","text":"Hey, Seven? Can I borrow you for\na second?","pose":2,"background":"","item":"","illustration":"","speaker_zh":"颂歌歌手","text_zh":"嘿，赛玟？我可以借你一下吗？"}]},{"id":122,"order":122,"actions":[{"uid":"410401101:122:1","speaker":"Seven","text":"Ah, sure.\nSorry, guys, be right back.","pose":10130108,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"啊，当然。对不起，伙计们，马上回来。"},{"uid":"410401101:122:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410401101:122:3","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":123,"order":123,"actions":[{"uid":"410401101:123:1","speaker":"Kirito","text":"Have fun.","pose":10011503,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"玩得开心。"},{"uid":"410401101:123:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":124,"order":124,"actions":[{"uid":"410401101:124:1","speaker":"Asuna","text":"I wonder what that caroler wanted\nwith Seven...","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"不知道那个颂歌者想要赛玟做什么……"}]},{"id":125,"order":125,"actions":[{"uid":"410401101:125:1","speaker":"Eugeo","text":"Hey, guys? I've been thinking...\nCarolers sing holy hymns, right?","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"嘿，伙计们？我一直在想...颂歌者唱圣歌，对吧？"},{"uid":"410401101:125:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":126,"order":126,"actions":[{"uid":"410401101:126:1","speaker":"Asuna","text":"Yeah, pretty much.\nWhy do you mention it?","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"嗯，差不多了。为什么提到它？"},{"uid":"410401101:126:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":127,"order":127,"actions":[{"uid":"410401101:127:1","speaker":"Eugeo","text":"Well, I was thinking... Maybe the\nmonsters just can't stand the\ndivine beauty of their songs?","pose":10530202,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"嗯，我在想……也许怪物们只是无法忍受他们歌曲的神圣之美？"},{"uid":"410401101:127:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":128,"order":128,"actions":[{"uid":"410401101:128:1","speaker":"Kirito","text":"Hmm...","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"嗯……"},{"uid":"410401101:128:2","speaker":"Asuna","text":"","pose":10020903,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":129,"order":129,"actions":[{"uid":"410401101:129:1","speaker":"Alice","text":"I thought the same. Additionally,\nI've heard that Pooka's\ninstruments and voices...","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我也是这么想的。另外，我听说过音乐精灵的乐器和声音……"},{"uid":"410401101:129:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":130,"order":130,"actions":[{"uid":"410401101:130:1","speaker":"Alice","text":"...have the strange power to\nenhance their listeners'\nabilities.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"……有一种奇怪的力量，可以增强听者的能力。"}]},{"id":131,"order":131,"actions":[{"uid":"410401101:131:1","speaker":"Kirito","text":"That's right... So you're saying\nmonsters don't like holy songs?\nI guess that makes sense, but...","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"是啊……你是说怪物不喜欢圣歌？我想这是有道理的，但是..."},{"uid":"410401101:131:2","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":132,"order":132,"actions":[{"uid":"410401101:132:1","speaker":"Alice","text":"Is there a flaw in my logic?","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我的逻辑有问题吗？"},{"uid":"410401101:132:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":133,"order":133,"actions":[{"uid":"410401101:133:1","speaker":"Kirito","text":"No, it's just that...then it all\nmakes even LESS sense...","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"不，只是这样……那就更没有意义了……"},{"uid":"410401101:133:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":134,"order":134,"actions":[{"uid":"410401101:134:1","speaker":"Alice","text":"Explain.","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"解释一下。"},{"uid":"410401101:134:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":135,"order":135,"actions":[{"uid":"410401101:135:1","speaker":"Eugeo","text":"...Kirito? We're waiting.","pose":10530203,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"...桐人？我们正在等待。"}]},{"id":136,"order":136,"actions":[{"uid":"410401101:136:1","speaker":"Asuna","text":"...","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"..."},{"uid":"410401101:136:2","speaker":"Kirito","text":"","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":137,"order":137,"actions":[{"uid":"410401101:137:1","speaker":"Kirito","text":"You know what, forget it.\nIt's nothing.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"你知道吗，算了。没什么。"}]},{"id":138,"order":138,"actions":[{"uid":"410401101:138:1","speaker":"Alice","text":"Explain.","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"解释一下。"},{"uid":"410401101:138:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":139,"order":139,"actions":[{"uid":"410401101:139:1","speaker":"Seven","text":"Sorry for the wait, guys...","pose":10130106,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"抱歉让大家久等了……"},{"uid":"410401101:139:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410401101:139:3","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":140,"order":140,"actions":[{"uid":"410401101:140:1","speaker":"Asuna","text":"Seven? You look upset...\nIs something wrong?","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"赛玟？你看起来很沮丧……有什么问题吗？"}]},{"id":141,"order":141,"actions":[{"uid":"410401101:141:1","speaker":"Seven","text":"Yeah, well... She told me she\nwanted to quit. I managed to\nconvince her not to, but...","pose":10130106,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"是啊，好吧……她告诉我她想退出。我设法说服她不要这么做，但是……"}]},{"id":142,"order":142,"actions":[{"uid":"410401101:142:1","speaker":"Asuna","text":"But...why?!","pose":100209112,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"但是……为什么？！"}]},{"id":143,"order":143,"actions":[{"uid":"410401101:143:1","speaker":"Seven","text":"We've been attacked so often,\nand that kid's gotten the death\npenalty so many times...","pose":10130106,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"我们经常被袭击，那小子也多次被判死刑……"}]},{"id":144,"order":144,"actions":[{"uid":"410401101:144:1","speaker":"Seven","text":"And I get it. It totally ruins\nyour day when you get killed...\nIt's just not fun.","pose":10130106,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"我明白了。当你被杀时，这完全毁了你的一天……这一点也不好玩。"}]},{"id":145,"order":145,"actions":[{"uid":"410401101:145:1","speaker":"Seven","text":"Some of the carolers just don't\nwant to keep dealing with the\nrisk anymore.","pose":10130106,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"一些颂歌者只是不想再继续面对风险了。"}]},{"id":146,"order":146,"actions":[{"uid":"410401101:146:1","speaker":"Kirito","text":"Hmm... I guess I can't blame them.","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"嗯……我想这也不能怪他们。"}]},{"id":147,"order":147,"actions":[{"uid":"410401101:147:1","speaker":"Kirito","text":"If I had elite mobs chasing me\nwherever I went, I'd be upset too.","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"如果我走到哪里都有精英怪追着我，我也会不高兴的。"}]},{"id":148,"order":148,"actions":[{"uid":"410401101:148:1","speaker":"Seven","text":"Yeah. I only convinced her to stay\nbecause you guys are here to keep\nus safe now.","pose":10130106,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"是的。我之所以说服她留下来，是因为你们现在来这里是为了保证我们的安全。"}]},{"id":149,"order":149,"actions":[{"uid":"410401101:149:1","speaker":"Asuna","text":"Oh, I see... Well, I'll do my\nbest to keep all of you safe!\nI swear it!","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"哦，原来如此……好吧，我会尽力保证你们的安全！我发誓！"}]},{"id":150,"order":150,"actions":[{"uid":"410401101:150:1","speaker":"Asuna","text":"You're with me, right?!","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"你在我身边吧？！"}]},{"id":151,"order":151,"actions":[{"uid":"410401101:151:1","speaker":"Alice","text":"Right.","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"对。"},{"uid":"410401101:151:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":152,"order":152,"actions":[{"uid":"410401101:152:1","speaker":"Eugeo","text":"Of course!","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"当然！"}]},{"id":153,"order":153,"actions":[{"uid":"410401101:153:1","speaker":"Kirito","text":"Hey, girls...","pose":10011505,"background":"bg_event_alne_field_christmas","item":"","illustration":"","speaker_zh":"桐人","text_zh":"嘿，姑娘们……"},{"uid":"410401101:153:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410401101:153:3","speaker":"Seven","text":"","pose":10130105,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":""}]},{"id":154,"order":154,"actions":[{"uid":"410401101:154:1","speaker":"Asuna","text":"Kirito? What's up?","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"桐人？这是怎么回事？"}]},{"id":155,"order":155,"actions":[{"uid":"410401101:155:1","speaker":"Kirito","text":"Where's Eugeo and Alice?","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"尤吉欧和爱丽丝在哪里？"}]},{"id":156,"order":156,"actions":[{"uid":"410401101:156:1","speaker":"Asuna","text":"They're in the back, acting as\nrear guard.","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"他们在后面，充当后卫。"}]},{"id":157,"order":157,"actions":[{"uid":"410401101:157:1","speaker":"Seven","text":"That's why we're up here, guarding\nthe front. Standard escort\npositioning.","pose":10130105,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"这就是我们在这里守卫前线的原因。标准护送定位。"}]},{"id":158,"order":158,"actions":[{"uid":"410401101:158:1","speaker":"Kirito","text":"Oh yeah...","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"噢耶……"}]},{"id":159,"order":159,"actions":[{"uid":"410401101:159:1","speaker":"Kirito","text":"I didn't want to say this in front\nof them before, but...","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"本来不想在他们面前说这些的，但是……"}]},{"id":160,"order":160,"actions":[{"uid":"410401101:160:1","speaker":"Kirito","text":"Here's the thing. I think we can\nall agree these monsters are\nDivine Object quest mobs...","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"事情是这样的。我想我们都同意这些怪物是神器任务小怪......"}]},{"id":161,"order":161,"actions":[{"uid":"410401101:161:1","speaker":"Kirito","text":"But that still doesn't add up.\nThere's just too much that\ndoesn't make sense here...","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"但这还是不行。这里有太多没有意义的东西......"}]},{"id":162,"order":162,"actions":[{"uid":"410401101:162:1","speaker":"Asuna","text":"I know what you mean...","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"我明白你的意思……"}]},{"id":163,"order":163,"actions":[{"uid":"410401101:163:1","speaker":"Seven","text":"You're talking about this special\nquest that started when Alice and\nEugeo came to our world, right?","pose":10130107,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"你说的是爱丽丝和尤吉欧来到我们的世界时开始的特殊任务吧？"}]},{"id":164,"order":164,"actions":[{"uid":"410401101:164:1","speaker":"Seven","text":"If I remember right, it's an auto-\ngenerated quest made by Cardinal\nto process this foreign data.","pose":10130102,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"如果我没记错的话，这是卡迪纳尔自动生成的任务，用于处理这些外部数据。"}]},{"id":165,"order":165,"actions":[{"uid":"410401101:165:1","speaker":"Kirito","text":"Yup. And your carolers are a\nbunch of players who got\ntogether for some fun.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"是的。你们的颂歌者是一群玩家，他们聚在一起寻找乐趣。"}]},{"id":166,"order":166,"actions":[{"uid":"410401101:166:1","speaker":"Kirito","text":"In other words, there's no logical\nlink between these quest monsters\nand you. It does not compute.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"也就是说，这些任务怪物和你之间没有逻辑上的联系。它不会计算。"}]},{"id":167,"order":167,"actions":[{"uid":"410401101:167:1","speaker":"Asuna","text":"It's got to have something to do\nwith the singing. Maybe holy hymns\nhurt them?","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"跟唱歌有关系吧。也许圣歌伤害了他们？"}]},{"id":168,"order":168,"actions":[{"uid":"410401101:168:1","speaker":"Kirito","text":"Well, I can see how that might\nwork, but it still doesn't add up.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"好吧，我知道这是怎么回事，但还是不太对劲。"}]},{"id":169,"order":169,"actions":[{"uid":"410401101:169:1","speaker":"Kirito","text":"If these monsters' orders are to\nattack \"those stupid fairies\nsinging their stupid songs,\"","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"如果这些怪物的命令是攻击“那些唱着愚蠢歌曲的愚蠢妖精”，"}]},{"id":170,"order":170,"actions":[{"uid":"410401101:170:1","speaker":"Kirito","text":"then something had to have the\npower to alter their default\nbehavior patterns.","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"那么某种东西就必须有能力改变他们默认的行为模式。"}]},{"id":171,"order":171,"actions":[{"uid":"410401101:171:1","speaker":"Seven","text":"I see what you're getting at.\nThe monsters are following\nsomeONE's orders, right?","pose":10130102,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"我明白你的意思了。怪物们是听从某个人的命令，对吗？"}]},{"id":172,"order":172,"actions":[{"uid":"410401101:172:1","speaker":"Seven","text":"That's the only explanation for\nwhy the system would change\ntheir behavior to attack us.","pose":10130102,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"这就是为什么系统会改变行为来攻击我们的唯一解释。"}]},{"id":173,"order":173,"actions":[{"uid":"410401101:173:1","speaker":"Kirito","text":"Exactly. And if we follow this\nthread to its logical conclusion,\nthere's only one possibility.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"没错。如果我们沿着这条线索得出逻辑结论，那就只有一种可能性。"}]},{"id":174,"order":174,"actions":[{"uid":"410401101:174:1","speaker":"Asuna","text":"Alice and Eugeo's Cait Sith NPC?","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"爱丽丝和尤吉欧的猫妖 NPC？"}]},{"id":175,"order":175,"actions":[{"uid":"410401101:175:1","speaker":"Kirito","text":"No, that's not entirely right.\nIf there's a Cait Sith ordering\nthese monsters to attack us...","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"不，不完全正确。如果有猫妖命令这些怪物攻击我们的话……"}]},{"id":176,"order":176,"actions":[{"uid":"410401101:176:1","speaker":"Kirito","text":"It's probably not an NPC...\nBut a player!!","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"可能不是NPC……而是玩家！！"}]},{"id":177,"order":177,"actions":[{"uid":"410401101:177:1","speaker":"Seven","text":"Ahhh, that makes sense! Even an\nNPC with a high-level AI probably\ncouldn't issue an order like that.","pose":10130107,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"啊啊，有道理！就算是拥有高级AI的NPC恐怕也无法发出这样的命令。"}]},{"id":178,"order":178,"actions":[{"uid":"410401101:178:1","speaker":"Asuna","text":"But why would a player even do\nthat?","pose":10020908,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"但是为什么玩家会这么做呢？"}]}]};
